369: func changeToWorkingCopy() {
370: 	workingDir := cfg.LocalWorkingDir()
371: 	cwd, err := tools.Getwd()
372: 	if err != nil {
373: 		ExitWithError(errors.Wrap(
374: 			err, tr.Tr.Get("Could not determine current working directory")))
375: 	}
376: 	cwd, err = tools.CanonicalizeSystemPath(cwd)
377: 	if err != nil {
378: 		ExitWithError(errors.Wrap(
379: 			err, tr.Tr.Get("Could not canonicalize current working directory")))
380: 	}
381: 
382: 	// If the current working directory is not within the repository's
383: 	// working directory, then let's change directories accordingly.  This
384: 	// should only occur if GIT_WORK_TREE is set.
385: 	if !(strings.HasPrefix(cwd, workingDir) && (cwd == workingDir || (len(cwd) > len(workingDir) && cwd[len(workingDir)] == os.PathSeparator))) {
386: 		os.Chdir(workingDir)
387: 	}
