416: func logPanic(loggedError error) string {
417: 	var (
418: 		fmtWriter  io.Writer = os.Stderr
419: 		lineEnding string    = "\n"
420: 	)
421: 
422: 	now := time.Now()
423: 	name := now.Format("20060102T150405.999999999")
424: 	full := filepath.Join(cfg.LocalLogDir(), name+".log")
425: 
426: 	if err := tools.MkdirAll(cfg.LocalLogDir(), cfg); err != nil {
427: 		full = ""
428: 		fmt.Fprintf(fmtWriter, "%s\n\n", tr.Tr.Get("Unable to log panic to '%s': %s", cfg.LocalLogDir(), err.Error()))
429: 	} else if file, err := os.Create(full); err != nil {
430: 		filename := full
431: 		full = ""
432: 		defer func() {
433: 			fmt.Fprintf(fmtWriter, "%s\n\n", tr.Tr.Get("Unable to log panic to '%s'", filename))
434: 			logPanicToWriter(fmtWriter, err, lineEnding)
435: 		}()
436: 	} else {
437: 		fmtWriter = file
438: 		lineEnding = gitLineEnding(cfg.Git)
439: 		defer file.Close()
440: 	}
441: 
442: 	logPanicToWriter(fmtWriter, loggedError, lineEnding)
443: 
444: 	return full
445: }
