447: func ipAddresses() []string {
448: 	ips := make([]string, 0, 1)
449: 	ifaces, err := net.Interfaces()
450: 	if err != nil {
451: 		ips = append(ips, tr.Tr.Get("Error getting network interface: %s", err.Error()))
452: 		return ips
453: 	}
454: 	for _, i := range ifaces {
455: 		if i.Flags&net.FlagUp == 0 {
456: 			continue // interface down
457: 		}
458: 		if i.Flags&net.FlagLoopback != 0 {
459: 			continue // loopback interface
460: 		}
461: 		addrs, _ := i.Addrs()
462: 		l := make([]string, 0, 1)
463: 		if err != nil {
464: 			ips = append(ips, tr.Tr.Get("Error getting IP address: %s", err.Error()))
465: 			continue
466: 		}
467: 		for _, addr := range addrs {
468: 			var ip net.IP
469: 			switch v := addr.(type) {
470: 			case *net.IPNet:
471: 				ip = v.IP
472: 			case *net.IPAddr:
473: 				ip = v.IP
474: 			}
475: 			if ip == nil || ip.IsLoopback() {
476: 				continue
477: 			}
478: 			l = append(l, ip.String())
479: 		}
480: 		if len(l) > 0 {
481: 			ips = append(ips, strings.Join(l, " "))
482: 		}
483: 	}
484: 	return ips
485: }
