487: func logPanicToWriter(w io.Writer, loggedError error, le string) {
488: 	// log the version
489: 	gitV, err := git.Version()
490: 	if err != nil {
491: 		gitV = tr.Tr.Get("Error getting Git version: %s", err.Error())
492: 	}
493: 
494: 	fmt.Fprint(w, config.VersionDesc, le)
495: 	fmt.Fprint(w, gitV, le)
496: 
497: 	// log the command that was run
498: 	fmt.Fprint(w, le)
499: 	fmt.Fprintf(w, "$ %s", filepath.Base(os.Args[0]))
500: 	if len(os.Args) > 0 {
501: 		fmt.Fprintf(w, " %s", strings.Join(os.Args[1:], " "))
502: 	}
503: 	fmt.Fprint(w, le)
504: 
505: 	// log the error message and stack trace
506: 	w.Write(ErrorBuffer.Bytes())
507: 	fmt.Fprint(w, le)
508: 
509: 	fmt.Fprintf(w, "%+v%s", loggedError, le)
510: 
511: 	for key, val := range errors.Context(err) {
512: 		fmt.Fprintf(w, "%s=%v%s", key, val, le)
513: 	}
514: 
515: 	fmt.Fprint(w, le, tr.Tr.Get("Current time in UTC:"), le)
516: 	fmt.Fprint(w, time.Now().UTC().Format("2006-01-02 15:04:05"), le)
517: 
518: 	fmt.Fprint(w, le, tr.Tr.Get("Environment:"), le)
519: 
520: 	// log the environment
521: 	for _, env := range lfs.Environ(cfg, getTransferManifest(), oldEnv) {
522: 		fmt.Fprint(w, env, le)
523: 	}
524: 
525: 	fmt.Fprint(w, le, tr.Tr.Get("Client IP addresses:"), le)
526: 
527: 	for _, ip := range ipAddresses() {
528: 		fmt.Fprint(w, ip, le)
529: 	}
530: }
