554: func determineFilepathFilterCache(config *config.Configuration) filepathfilter.Option {
555: 	cacheSize := defaultFilepathFilterCacheSize
556: 
557: 	if configSize, ok := config.Git.Get("lfs.pathfiltercachesize"); ok {
558: 		switch configSize {
559: 		case "none":
560: 			return filepathfilter.DisableCache()
561: 		case "unlimited":
562: 			cacheSize = 0
563: 		default:
564: 			if s, err := strconv.Atoi(configSize); err == nil {
565: 				if s == 0 {
566: 					return filepathfilter.DisableCache()
567: 				} else if s > 0 {
568: 					cacheSize = s
569: 				}
570: 			}
571: 		}
572: 	}
573: 
574: 	return filepathfilter.EnableCache(cacheSize)
575: }
