88: // CleanPaths splits the given `paths` argument by the delimiter argument, and
89: // then "cleans" that path according to the path.Clean function (see
90: // https://golang.org/pkg/path#Clean).
91: // Note always cleans to '/' path separators regardless of platform (git friendly)
92: func CleanPaths(paths, delim string) (cleaned []string) {
93: 	// If paths is an empty string, splitting it will yield [""], which will
94: 	// become the path ".". To avoid this, bail out if trimmed paths
95: 	// argument is empty.
96: 	if paths = strings.TrimSpace(paths); len(paths) == 0 {
97: 		return
98: 	}
99: 
100: 	for _, part := range strings.Split(paths, delim) {
101: 		part = strings.TrimSpace(part)
102: 
103: 		// Remove trailing `/` or `\`, but only the first one.
104: 		for _, sep := range []string{`/`, `\`} {
105: 			if strings.HasSuffix(part, sep) {
106: 				part = strings.TrimSuffix(part, sep)
107: 				break
108: 			}
109: 		}
110: 
111: 		cleaned = append(cleaned, part)
112: 	}
113: 
114: 	return cleaned
115: }
