289: func fastWalkDir(dir string) *fastWalker {
290: 	limit, _ := strconv.Atoi(os.Getenv("LFS_FASTWALK_LIMIT"))
291: 	if limit < 1 {
292: 		limit = runtime.GOMAXPROCS(-1) * 20
293: 	}
294: 
295: 	c := int32(0)
296: 	w := &fastWalker{
297: 		dir:   dir,
298: 		limit: int32(limit),
299: 		cur:   &c,
300: 		ch:    make(chan fastWalkInfo, 256),
301: 		wg:    &sync.WaitGroup{},
302: 	}
303: 
304: 	go func() {
305: 		defer w.Wait()
306: 
307: 		dirFi, err := os.Stat(w.dir)
308: 		if err != nil {
309: 			w.ch <- fastWalkInfo{Err: err}
310: 			return
311: 		}
