318: // Walk is the main recursive implementation of fast walk.  Sends the file/dir
319: // and any contents to the channel.  Increments waitg.Add(1) for each new
320: // goroutine launched internally
321: //
322: // dir - Relative path inside the directory being walked
323: func (w *fastWalker) Walk(isInitialDir bool, dir string, itemFi os.FileInfo) {
324: 
325: 	var fullPath string  // Absolute path to the current file or dir
326: 	var parentDir string // Absolute path to the parent of the current item
327: 	if isInitialDir {
328: 		fullPath = w.dir
329: 	} else {
330: 		parentDir = join(w.dir, dir)
331: 		fullPath = join(parentDir, itemFi.Name())
332: 	}
333: 
334: 	w.ch <- fastWalkInfo{ParentDir: parentDir, Info: itemFi}
335: 
336: 	if !itemFi.IsDir() {
337: 		// Nothing more to do if this is not a dir
338: 		return
339: 	}
340: 
341: 	var childDir string
342: 	if !isInitialDir {
343: 		childDir = join(dir, itemFi.Name())
344: 	}
345: 
346: 	// The absolute optimal way to scan would be File.Readdirnames but we
347: 	// still need the Stat() to know whether something is a dir, so use
348: 	// File.Readdir instead. Means we can provide os.FileInfo to callers like
349: 	// filepath.Walk as a bonus.
350: 	df, err := os.Open(fullPath)
351: 	if err != nil {
352: 		w.ch <- fastWalkInfo{Err: err}
353: 		return
354: 	}
355: 
356: 	// The number of items in a dir we process in each goroutine
357: 	jobSize := 100
358: 	for children, err := df.Readdir(jobSize); err == nil; children, err = df.Readdir(jobSize) {
359: 		// Parallelise all dirs, and chop large dirs into batches
360: 		w.walk(children, func(subitems []os.FileInfo) {
361: 			for _, childFi := range subitems {
362: 				w.Walk(false, childDir, childFi)
363: 			}
364: 		})
365: 	}
366: 
367: 	df.Close()
368: 	if err != nil && err != io.EOF {
369: 		w.ch <- fastWalkInfo{Err: err}
370: 	}
371: }
