373: func (w *fastWalker) walk(children []os.FileInfo, fn func([]os.FileInfo)) {
374: 	cur := atomic.AddInt32(w.cur, 1)
375: 	if cur > w.limit {
376: 		fn(children)
377: 		atomic.AddInt32(w.cur, -1)
378: 		return
379: 	}
380: 
381: 	w.wg.Add(1)
382: 	go func() {
383: 		fn(children)
384: 		w.wg.Done()
385: 		atomic.AddInt32(w.cur, -1)
386: 	}()
387: }
