405: // SetFileWriteFlag changes write permissions on a file
406: // Used to make a file read-only or not. When writeEnabled = false, the write
407: // bit is removed for all roles. When writeEnabled = true, the behaviour is
408: // different per platform:
409: // On Mac & Linux, the write bit is set only on the owner as per default umask.
410: // All other bits are unaffected.
411: // On Windows, all the write bits are set since Windows doesn't support Unix permissions.
412: func SetFileWriteFlag(path string, writeEnabled bool) error {
413: 	stat, err := os.Stat(path)
414: 	if err != nil {
415: 		return err
416: 	}
417: 	mode := uint32(stat.Mode())
418: 
419: 	if (writeEnabled && (mode&0200) > 0) ||
420: 		(!writeEnabled && (mode&0222) == 0) {
421: 		// no change needed
422: 		return nil
423: 	}
424: 
425: 	if writeEnabled {
426: 		mode = mode | 0200 // set owner write only
427: 		// Go's own Chmod makes Windows set all though
428: 	} else {
429: 		mode = mode &^ 0222 // disable all write
430: 	}
431: 	return os.Chmod(path, os.FileMode(mode))
432: }
