134: 		// Initial `\n` to avoid overprinting `Downloading LFS...`.
135: 		fmt.Fprint(os.Stderr, "\n", tr.Tr.Get(`hint: The remote resolves to a file:// URL, which can only work with a
136: hint: standalone transfer agent.  See section "Using a Custom Transfer Type
137: hint: without the API server" in custom-transfers.md for details.`), "\n")
138: 	}
139: 
140: 	sshRes, err := c.sshResolveWithRetries(e, method)
141: 	if err != nil {
142: 		return nil, err
143: 	}
144: 
145: 	prefix := e.Url
146: 	if len(sshRes.Href) > 0 {
147: 		prefix = sshRes.Href
148: 	}
149: 
150: 	if !httpRE.MatchString(prefix) {
151: 		urlfragment := strings.SplitN(prefix, "?", 2)[0]
152: 		return nil, errors.New(tr.Tr.Get("missing protocol: %q", urlfragment))
153: 	}
154: 
155: 	req, err := http.NewRequest(method, joinURL(prefix, suffix), nil)
156: 	if err != nil {
157: 		return req, err
158: 	}
159: 
160: 	for key, value := range sshRes.Header {
161: 		req.Header.Set(key, value)
162: 	}
163: 	req.Header.Set("Accept", MediaType)
164: 
165: 	if body != nil {
166: 		if merr := MarshalToRequest(req, body); merr != nil {
167: 			return req, merr
168: 		}
169: 		req.Header.Set("Content-Type", RequestContentType)
170: 	}
171: 
172: 	return req, err
173: }
