225: func (c *Client) sshResolveWithRetries(e Endpoint, method string) (*sshAuthResponse, error) {
226: 	var sshRes sshAuthResponse
227: 	var err error
228: 
229: 	uc := config.NewURLConfig(c.gitEnv)
230: 	if val, ok := uc.Get("lfs", e.OriginalUrl, "sshtransfer"); ok && val != "negotiate" && val != "never" {
231: 		tracerx.Printf("skipping SSH-HTTPS hybrid protocol connection by request")
232: 		return nil, errors.New("git-lfs-authenticate has been disabled by request")
233: 	}
234: 
235: 	requests := max(0, c.sshTries) + 1
236: 	for i := 0; i < requests; i++ {
237: 		sshRes, err = c.SSH.Resolve(e, method)
238: 		if err == nil {
239: 			return &sshRes, nil
240: 		}
241: 
242: 		tracerx.Printf(
243: 			"ssh: %s failed, error: %s, message: %s (try: %d/%d)",
244: 			e.SSHMetadata.UserAndHost, err.Error(), sshRes.Message, i,
245: 			requests,
246: 		)
247: 	}
248: 
249: 	if len(sshRes.Message) > 0 {
250: 		return nil, errors.Wrap(err, sshRes.Message)
251: 	}
252: 	return nil, err
253: }
