255: func (c *Client) ExtraHeadersFor(req *http.Request) http.Header {
256: 	extraHeaders := c.extraHeaders(req.URL)
257: 	if len(extraHeaders) == 0 {
258: 		return req.Header
259: 	}
260: 
261: 	copy := make(http.Header, len(req.Header))
262: 	for k, vs := range req.Header {
263: 		copy[k] = vs
264: 	}
265: 
266: 	for k, vs := range extraHeaders {
267: 		for _, v := range vs {
268: 			if !slices.Contains(copy[k], v) {
269: 				copy[k] = append(copy[k], v)
270: 			}
271: 		}
272: 	}
273: 	return copy
274: }
