276: func (c *Client) extraHeaders(u *url.URL) map[string][]string {
277: 	hdrs := c.uc.GetAll("http", u.String(), "extraHeader")
278: 	m := make(map[string][]string, len(hdrs))
279: 
280: 	for _, hdr := range hdrs {
281: 		parts := strings.SplitN(hdr, ":", 2)
282: 		if len(parts) < 2 {
283: 			continue
284: 		}
285: 
286: 		k, v := parts[0], strings.TrimSpace(parts[1])
287: 		// If header keys are given in non-canonicalized form (e.g.,
288: 		// "AUTHORIZATION" as opposed to "Authorization") they will not
289: 		// be returned in calls to net/http.Header.Get().
290: 		//
291: 		// So, we avoid this problem by first canonicalizing header keys
292: 		// for extra headers.
293: 		k = textproto.CanonicalMIMEHeaderKey(k)
294: 
295: 		m[k] = append(m[k], v)
296: 	}
297: 	return m
298: }
