300: func (c *Client) DoWithRedirect(cli *http.Client, req *http.Request, remote string, via []*http.Request) (*http.Request, *http.Response, error) {
301: 	tracedReq, err := c.traceRequest(req)
302: 	if err != nil {
303: 		return nil, nil, err
304: 	}
305: 
306: 	var retries int
307: 	if n, ok := Retries(req); ok {
308: 		retries = n
309: 	} else {
310: 		retries = defaultRequestRetries
311: 	}
312: 
313: 	var res *http.Response
314: 
315: 	requests := max(0, retries) + 1
316: 	for i := 0; i < requests; i++ {
317: 		res, err = cli.Do(req)
318: 		if err == nil {
319: 			break
320: 		}
321: 
322: 		if seek, ok := req.Body.(io.Seeker); ok {
323: 			seek.Seek(0, io.SeekStart)
324: 		}
325: 
326: 		c.traceResponse(req, tracedReq, nil)
327: 	}
328: 
329: 	if err != nil {
330: 		c.traceResponse(req, tracedReq, nil)
331: 		// SPNEGO (Negotiate) errors are authentication errors.
332: 		var spnegoErr *spnego.Error
333: 		if goerrors.As(err, &spnegoErr) {
334: 			tracerx.Printf("http: got Negotiate error: %s", spnegoErr.Error())
335: 			return nil, nil, errors.NewAuthError(err)
336: 		}
337: 		return nil, nil, err
338: 	}
339: 
340: 	if res == nil {
341: 		return nil, nil, nil
342: 	}
343: 
344: 	if res.Uncompressed {
345: 		tracerx.Printf("http: decompressed gzipped response")
346: 	}
347: 
348: 	c.traceResponse(req, tracedReq, res)
349: 
350: 	if res.StatusCode != 301 &&
351: 		res.StatusCode != 302 &&
352: 		res.StatusCode != 303 &&
353: 		res.StatusCode != 307 &&
354: 		res.StatusCode != 308 {
355: 
356: 		// Above are the list of 3xx status codes that we know
357: 		// how to handle below. If the status code contained in
358: 		// the HTTP response was none of them, return the (res,
359: 		// err) tuple as-is, otherwise handle the redirect.
360: 		return nil, res, c.handleResponse(res)
361: 	}
362: 
363: 	redirectTo := res.Header.Get("Location")
364: 	locurl, err := url.Parse(redirectTo)
365: 	if err == nil && !locurl.IsAbs() {
366: 		locurl = req.URL.ResolveReference(locurl)
367: 		redirectTo = locurl.String()
368: 	}
369: 
370: 	via = append(via, req)
371: 	if len(via) >= 3 {
372: 		return nil, res, errors.New(tr.Tr.Get("too many redirects"))
373: 	}
374: 
375: 	redirectedReq, err := newRequestForRetry(req, redirectTo)
376: 	if err != nil {
377: 		return nil, res, err
378: 	}
379: 
380: 	res.Body.Close()
381: 
382: 	return redirectedReq, nil, nil
383: }
