385: func (c *Client) doWithRedirects(cli *http.Client, req *http.Request, remote string, via []*http.Request) (*http.Response, error) {
386: 	redirectedReq, res, err := c.DoWithRedirect(cli, req, remote, via)
387: 	if err != nil || res != nil {
388: 		return res, err
389: 	}
390: 
391: 	if redirectedReq == nil {
392: 		return nil, errors.New(tr.Tr.Get("failed to redirect request"))
393: 	}
394: 
395: 	return c.doWithRedirects(cli, redirectedReq, remote, via)
