398: func (c *Client) configureProtocols(u *url.URL, transport *http.Transport) error {
399: 	version, _ := c.uc.Get("http", u.String(), "version")
400: 	switch version {
401: 	case "HTTP/1.1":
402: 		// This disables HTTP/2, according to the documentation.
403: 		transport.TLSNextProto = make(map[string]func(authority string, c *tls.Conn) http.RoundTripper)
404: 	case "HTTP/2":
405: 		if u.Scheme != "https" {
406: 			return errors.New(tr.Tr.Get("HTTP/2 cannot be used except with TLS"))
407: 		}
408: 		http2.ConfigureTransport(transport)
409: 		delete(transport.TLSNextProto, "http/1.1")
410: 	case "":
411: 		http2.ConfigureTransport(transport)
412: 	default:
413: 		return errors.New(tr.Tr.Get("Unknown HTTP version %q", version))
414: 	}
415: 	return nil
416: }
