418: func (c *Client) Transport(u *url.URL, access creds.AccessMode) (http.RoundTripper, error) {
419: 	host := u.Host
420: 
421: 	if c.gitEnv == nil {
422: 		c.gitEnv = make(testEnv)
423: 	}
424: 
425: 	if c.osEnv == nil {
426: 		c.osEnv = make(testEnv)
427: 	}
428: 
429: 	concurrentTransfers := c.ConcurrentTransfers
430: 	if concurrentTransfers < 1 {
431: 		concurrentTransfers = DefaultConcurrentTransfers()
432: 	}
433: 
434: 	dialtime := c.DialTimeout
435: 	if dialtime < 1 {
436: 		dialtime = 30
437: 	}
438: 
439: 	keepalivetime := c.KeepaliveTimeout
440: 	if keepalivetime < 1 {
441: 		keepalivetime = 1800
442: 	}
443: 
444: 	tlstime := c.TLSTimeout
445: 	if tlstime < 1 {
446: 		tlstime = 30
447: 	}
448: 	tr := &http.Transport{
449: 		Proxy:               proxyFromClient(c),
450: 		TLSHandshakeTimeout: time.Duration(tlstime) * time.Second,
451: 		MaxIdleConnsPerHost: concurrentTransfers,
452: 	}
453: 
454: 	activityTimeout := 30
455: 	if v, ok := c.uc.Get("lfs", u.String(), "activitytimeout"); ok {
456: 		if i, err := strconv.Atoi(v); err == nil {
457: 			activityTimeout = i
458: 		} else {
459: 			activityTimeout = 0
460: 		}
461: 	}
462: 
463: 	dialer := &net.Dialer{
464: 		Timeout:   time.Duration(dialtime) * time.Second,
465: 		KeepAlive: time.Duration(keepalivetime) * time.Second,
466: 		DualStack: true,
467: 	}
468: 
469: 	if activityTimeout > 0 {
470: 		activityDuration := time.Duration(activityTimeout) * time.Second
471: 		tr.DialContext = func(ctx context.Context, network, addr string) (net.Conn, error) {
472: 			c, err := dialer.DialContext(ctx, network, addr)
473: 			if c == nil {
474: 				return c, err
475: 			}
476: 			if tc, ok := c.(*net.TCPConn); ok {
477: 				tc.SetKeepAlive(true)
478: 				tc.SetKeepAlivePeriod(dialer.KeepAlive)
479: 			}
480: 			return &deadlineConn{Timeout: activityDuration, Conn: c}, err
481: 		}
482: 	} else {
483: 		tr.DialContext = dialer.DialContext
484: 	}
485: 
486: 	tr.TLSClientConfig = &tls.Config{
487: 		Renegotiation: tls.RenegotiateFreelyAsClient,
488: 	}
489: 
490: 	if isClientCertEnabledForHost(c, host) {
491: 		tracerx.Printf("http: client cert for %s", host)
492: 		cert, err := getClientCertForHost(c, host)
493: 		if err != nil {
494: 			return nil, err
495: 		}
496: 		if cert != nil {
497: 			tr.TLSClientConfig.Certificates = []tls.Certificate{*cert}
498: 			tr.TLSClientConfig.BuildNameToCertificate()
499: 		}
500: 	}
501: 
502: 	if isCertVerificationDisabledForHost(c, host) {
503: 		tr.TLSClientConfig.InsecureSkipVerify = true
504: 	} else {
505: 		tr.TLSClientConfig.RootCAs = getRootCAsForHostFromGitconfig(c, host)
506: 	}
507: 
508: 	if err := c.configureProtocols(u, tr); err != nil {
509: 		return nil, err
510: 	}
511: 
512: 	if access == creds.NegotiateAccess {
513: 		// This technically copies a mutex, but we know since we've just created
514: 		// the object that this mutex is unlocked.
515: 		return &spnego.Transport{Transport: *tr}, nil
516: 	}
517: 	return tr, nil
518: }
