571: func newRequestForRetry(req *http.Request, location string) (*http.Request, error) {
572: 	newReq, err := http.NewRequest(req.Method, location, nil)
573: 	if err != nil {
574: 		return nil, err
575: 	}
576: 
577: 	if req.URL.Scheme == "https" && newReq.URL.Scheme == "http" {
578: 		return nil, errors.New(tr.Tr.Get("refusing insecure redirect: HTTPS to HTTP"))
579: 	}
580: 
581: 	sameHost := req.URL.Host == newReq.URL.Host
582: 	for key := range req.Header {
583: 		if key == "Authorization" {
584: 			if !sameHost {
585: 				continue
586: 			}
587: 		}
588: 		newReq.Header.Set(key, req.Header.Get(key))
589: 	}
590: 
591: 	oldestURL := strings.SplitN(req.URL.String(), "?", 2)[0]
592: 	newURL := strings.SplitN(newReq.URL.String(), "?", 2)[0]
593: 	tracerx.Printf("api: redirect %s %s to %s", req.Method, oldestURL, newURL)
594: 
595: 	// This body will have already been rewound from a call to
596: 	// lfsapi.Client.traceRequest().
597: 	newReq.Body = req.Body
598: 	newReq.ContentLength = req.ContentLength
599: 
600: 	// Copy the request's context.Context, if any.
601: 	newReq = newReq.WithContext(req.Context())
602: 
603: 	return newReq, nil
604: }
